// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadNotoSans = makeLoadFont('NotoSans');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: notoSansFamily } = loadNotoSans();



export type SimpleLowerThirdProps = Record<string, any>;

const SimpleLowerThird: React.FC<SimpleLowerThirdProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  boxColor = "#1a223e",
  titleText = "MALLOY STUDIO",
  subtitleText = "Lead Visual Design",
  boxWidthPercent = 0.38,
  boxHeightPercent = 0.16,
  bottomMarginPercent = 0.12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimensions based on percentages
  const actualBoxWidth = width * boxWidthPercent;
  const actualBoxHeight = height * boxHeightPercent;
  const bottomPosition = height * bottomMarginPercent;

  // --- Animation Timing ---
  const exitDuration = 30; // frames
  const startExitFrame = durationInSeconds * fps - exitDuration;

  // Spring to slide in
  const entranceSpring = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8, stiffness: 100 },
  });

  // Spring to slide out
  const exitSpring = spring({
    fps,
    frame: Math.max(0, frame - startExitFrame),
    config: { damping: 14, mass: 0.8, stiffness: 100 },
  });

  // Combined progress: goes 0 -> 1 ... stays at 1 ... 1 -> 0
  const boxProgress = entranceSpring - exitSpring;

  // Box positions
  const boxX = interpolate(boxProgress, [0, 1], [-actualBoxWidth, 0]);

  // --- Text Animation ---
  // Stagger the text entry slightly after the box
  const textEntryFrame = frame - 10;
  
  const textSpring = spring({
    fps,
    frame: textEntryFrame,
    config: { damping: 12 },
  });

  // Text exits at the same time as the box, but faster
  const textExitSpring = spring({
    fps,
    frame: Math.max(0, frame - (startExitFrame - 5)),
    config: { damping: 12 },
  });

  const textProgress = textSpring - textExitSpring;
  
  const textOpacity = interpolate(textProgress, [0, 1], [0, 1]);
  const textY = interpolate(textProgress, [0, 1], [20, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Lower Third Container */}
      <div
        style={{
          position: "absolute",
          left: boxX,
          bottom: bottomPosition,
          width: actualBoxWidth,
          height: actualBoxHeight,
          backgroundColor: boxColor,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: "5%",
          transition: "none",
        }}
      >
        {/* Text Wrapper for staggered reveal */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textY}px)`,
            display: "flex",
            flexDirection: "column",
            gap: "8px",
            transition: "none",
          }}
        >
          {titleText && (
            <div
              style={{
                fontFamily: notoSansFamily,
                fontWeight: 800,
                fontSize: actualBoxHeight * 0.25,
                color: "#ffffff",
                letterSpacing: "0.05em",
                textTransform: "uppercase",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {titleText}
            </div>
          )}
          
          {subtitleText && (
            <div
              style={{
                fontFamily: notoSansFamily,
                fontWeight: 400,
                fontSize: actualBoxHeight * 0.16,
                color: "rgba(255, 255, 255, 0.7)",
                letterSpacing: "0.02em",
                lineHeight: 1,
                transition: "none",
              }}
            >
              {subtitleText}
            </div>
          )}
        </div>
      </div>
      
    </AbsoluteFill>
  );
};

export default SimpleLowerThird;